import random
import struct
import zlib

def _crc(chunk_type: bytes, data: bytes) -> int:
    return zlib.crc32(chunk_type + data) & 0xFFFFFFFF

def _chunk(chunk_type: bytes, data: bytes) -> bytes:
    return struct.pack(">I", len(data)) + chunk_type + data + struct.pack(">I", _crc(chunk_type, data))

def _ihdr(width: int, height: int, bitdepth: int = 8, colortype: int = 6, interlace: int = 0) -> bytes:
    # color type 6 = RGBA, bit depth 8, compression/filter methods 0
    return _chunk(b'IHDR', struct.pack(">IIBBBBB", width, height, bitdepth, colortype, 0, 0, interlace))

def _idat_raw_rgba(width: int, height: int, pattern: int) -> bytes:
    # Build uncompressed scanlines with filter type 0 and a simple pattern
    # RGBA per pixel
    bpp = 4
    scan = bytearray()
    for y in range(height):
        scan.append(0)  # filter type 0
        for x in range(width):
            # Generate a few deterministic patterns based on pattern id
            if pattern == 0:
                r = (x * 13 + y * 7) & 0xFF
                g = (x * 3 + y * 11) & 0xFF
                b = (x ^ y) & 0xFF
                a = 255
            elif pattern == 1:
                r = (y * 17) & 0xFF
                g = (x * 29) & 0xFF
                b = ((x + y) * 5) & 0xFF
                a = 255
            elif pattern == 2:
                # checkerboard with transparency
                chk = ((x >> 3) + (y >> 3)) & 1
                v = 255 if chk else 32
                r = v; g = v; b = v; a = 255 if chk else 64
            else:
                # solid with varying alpha by row
                r = 50; g = 100; b = 150; a = (y * 255 // max(1, height - 1)) & 0xFF
            scan.extend((r, g, b, a))
    comp = zlib.compress(bytes(scan), level=6)
    return _chunk(b'IDAT', comp)

def _text_chunks(rng: random.Random) -> bytes:
    # Add one or two tEXt chunks with simple ASCII to exercise chunk parsing
    chunks = []
    texts = [
        (b"Title", b"Sample PNG"),
        (b"Author", b"libgd-fuzz"),
        (b"Description", b"Generated valid PNG for fuzz seed"),
    ]
    rng.shuffle(texts)
    count = rng.randint(0, 2)
    for i in range(count):
        k, v = texts[i]
        chunks.append(_chunk(b"tEXt", k + b"\x00" + v))
    return b"".join(chunks)

def _phys_chunk(rng: random.Random) -> bytes:
    # Optional physical pixel dimensions
    if rng.random() < 0.5:
        ppu_x = rng.choice([2835, 3780, 4724, 0])  # common values (~72/96/120 DPI) or unknown
        ppu_y = rng.choice([2835, 3780, 4724, 0])
        unit = rng.choice([0, 1])
        data = struct.pack(">IIB", ppu_x, ppu_y, unit)
        return _chunk(b"pHYs", data)
    return b""

def _srgb_gama_chunks(rng: random.Random) -> bytes:
    out = []
    choice = rng.random()
    if choice < 0.33:
        out.append(_chunk(b"sRGB", bytes([rng.choice([0, 1, 2, 3])])))
    elif choice < 0.66:
        # gAMA value is image gamma * 100000, typical 45455 (~1/2.2)
        out.append(_chunk(b"gAMA", struct.pack(">I", rng.choice([45455, 50000, 0x000186A0]))))
    else:
        # both sometimes
        out.append(_chunk(b"sRGB", b"\x00"))
        out.append(_chunk(b"gAMA", struct.pack(">I", 45455)))
    return b"".join(out)

def _palette_png(rng: random.Random, width: int, height: int) -> bytes:
    # Indexed-color PNG (color type 3) with PLTE and tRNS to exercise different loader paths
    bitdepth = rng.choice([1, 2, 4, 8])
    ihdr = _chunk(b"IHDR", struct.pack(">IIBBBBB", width, height, bitdepth, 3, 0, 0, 0))

    # build a palette of up to 256 colors (multiple of 3 bytes)
    max_colors = 1 << bitdepth
    palette_size = rng.randint(max(2, max_colors // 2), max_colors)
    plte = bytearray()
    for i in range(palette_size):
        plte.extend((rng.randrange(256), rng.randrange(256), rng.randrange(256)))
    plte_chunk = _chunk(b"PLTE", bytes(plte))

    # optional transparency for some leading entries
    trns = b""
    if rng.random() < 0.6:
        count = rng.randint(1, min(8, palette_size))
        trns = _chunk(b"tRNS", bytes(rng.randrange(1, 256) for _ in range(count)))

    # build indexed image data
    # each scanline: filter byte + indices packed according to bitdepth
    def pack_indices(row_idx):
        idxs = [ (x + row_idx) % palette_size for x in range(width) ]
        if bitdepth == 8:
            return bytes(idxs)
        elif bitdepth == 4:
            out = bytearray()
            for i in range(0, len(idxs), 2):
                a = idxs[i]
                b = idxs[i+1] if i+1 < len(idxs) else 0
                out.append(((a & 0xF) << 4) | (b & 0xF))
            return bytes(out)
        elif bitdepth == 2:
            out = bytearray()
            for i in range(0, len(idxs), 4):
                vals = idxs[i:i+4] + [0]*4
                a,b,c,d = vals[0], vals[1], vals[2], vals[3]
                out.append(((a & 3)<<6)|((b & 3)<<4)|((c & 3)<<2)|(d & 3))
            return bytes(out)
        else:  # 1-bit
            out = bytearray()
            for i in range(0, len(idxs), 8):
                byte = 0
                for bit in range(8):
                    v = idxs[i+bit] if i+bit < len(idxs) else 0
                    byte |= ((v & 1) << (7-bit))
                out.append(byte)
            return bytes(out)

    raw = bytearray()
    for y in range(height):
        raw.append(0)  # filter type 0
        raw.extend(pack_indices(y))
    idat = _chunk(b"IDAT", zlib.compress(bytes(raw), level=6))
    iend = _chunk(b"IEND", b"")

    return b"\x89PNG\r\n\x1a\n" + ihdr + plte_chunk + trns + _text_chunks(rng) + _phys_chunk(rng) + idat + iend

def _truecolor_png(rng: random.Random, width: int, height: int) -> bytes:
    signature = b"\x89PNG\r\n\x1a\n"
    ihdr = _ihdr(width, height, bitdepth=8, colortype=rng.choice([2, 6]))  # RGB or RGBA

    # If RGB (color type 2), generate RGB data; if RGBA, generate RGBA
    color_type = ihdr[12+8]  # chunk type starts at 12, IHDR data starts after 8 bytes of length+type
    if color_type == 2:
        # build raw RGB scanlines
        scan = bytearray()
        for y in range(height):
            scan.append(0)
            for x in range(width):
                r = (x * 5 + y * 7) & 0xFF
                g = (x * 11 + y * 3) & 0xFF
                b = (x ^ (255 - y)) & 0xFF
                scan.extend((r, g, b))
        idat = _chunk(b"IDAT", zlib.compress(bytes(scan), level=6))
    else:
        idat = _idat_raw_rgba(width, height, rng.randrange(0, 4))

    extras = _text_chunks(rng) + _phys_chunk(rng) + _srgb_gama_chunks(rng)
    iend = _chunk(b"IEND", b"")
    return signature + ihdr + extras + idat + iend

def _choose_dims(rng: random.Random):
    # Keep reasonably small but varied; include some edge-y sizes
    choices = [1, 2, 3, 4, 8, 16, 32, 64, 128]
    w = rng.choice(choices)
    h = rng.choice(choices)
    return w, h

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    w, h = _choose_dims(rng)

    # Choose between palette or truecolor variants
    if rng.random() < 0.4:
        png = _palette_png(rng, w, h)
    else:
        png = _truecolor_png(rng, w, h)

    # Ensure under 4096 bytes when possible by limiting dimensions; if over, reduce by choosing smaller dims deterministically
    if len(png) > 4096:
        # fallback to tiny RGBA image
        png = _truecolor_png(rng, 8, 8)
    return png

import random
import struct
import zlib
from typing import List, Tuple

# This generator builds minimal but valid PNG images with variations that exercise
# libgd PNG loaders via memory buffers, gdIOCtx, and FILE* inputs.
# It supports different color types, bit depths, dimensions, and optional chunks.

PNG_SIG = b"\x89PNG\r\n\x1a\n"

# CRC helper

def _crc32(data: bytes) -> int:
    return zlib.crc32(data) & 0xFFFFFFFF


def _png_chunk(ctype: bytes, data: bytes) -> bytes:
    length = struct.pack('>I', len(data))
    crc = struct.pack('>I', _crc32(ctype + data))
    return length + ctype + data + crc


def _ihdr(width: int, height: int, bitdepth: int, colortype: int, interlace: int = 0) -> bytes:
    # Compression method 0, filter method 0
    data = struct.pack('>IIBBBBB', width, height, bitdepth, colortype, 0, 0, interlace)
    return _png_chunk(b'IHDR', data)


def _idat(raw_scanlines: bytes) -> bytes:
    comp = zlib.compress(raw_scanlines, level=6)
    return _png_chunk(b'IDAT', comp)


def _iend() -> bytes:
    return _png_chunk(b'IEND', b'')


def _chunk_gama(gamma_100k: int) -> bytes:
    # gamma is stored as 4-byte unsigned integer times 100000
    return _png_chunk(b'gAMA', struct.pack('>I', gamma_100k))


def _chunk_phys(ppux: int, ppuy: int, unit: int) -> bytes:
    return _png_chunk(b'pHYs', struct.pack('>IIB', ppux, ppuy, unit))


def _chunk_text(keyword: str, text: str) -> bytes:
    key_b = keyword.encode('latin-1', errors='ignore')[:79]
    text_b = text.encode('latin-1', errors='ignore')
    return _png_chunk(b'tEXt', key_b + b'\x00' + text_b)


def _filter_none_scanlines(row_bytes: int, rows: List[bytes]) -> bytes:
    # Prepend filter type 0 for each row
    return b''.join(b'\x00' + r for r in rows)


def _pack_samples(samples: List[int], bits: int) -> bytes:
    # Pack samples for grayscale with bitdepth 1,2,4,8,16
    if bits == 8:
        return bytes(samples)
    if bits == 16:
        # big-endian per PNG spec
        return b''.join(struct.pack('>H', min(65535, max(0, s))) for s in samples)
    # For 1,2,4 pack into bytes msb-first
    out = bytearray()
    acc = 0
    filled = 0
    mask = (1 << bits) - 1
    for s in samples:
        acc = (acc << bits) | (s & mask)
        filled += bits
        if filled >= 8:
            out.append((acc >> (filled - 8)) & 0xFF)
            filled -= 8
            acc &= (1 << filled) - 1
    if filled > 0:
        out.append((acc << (8 - filled)) & 0xFF)
    return bytes(out)


def _build_rows_grayscale(w: int, h: int, bitdepth: int, rng: random.Random) -> List[bytes]:
    maxv = (1 << bitdepth) - 1 if bitdepth <= 8 else 65535
    rows = []
    for y in range(h):
        # simple gradient + randomness
        samples = [int(maxv * (y / max(1, h-1))) for _ in range(w)]
        # sprinkle some noise
        for i in range(0, w, max(1, w // 8)):
            samples[i] = rng.randrange(0, maxv + 1)
        rows.append(_pack_samples(samples, bitdepth))
    return rows


def _build_rows_rgb(w: int, h: int, bitdepth: int, rng: random.Random) -> List[bytes]:
    # 8-bit or 16-bit
    chan_max = 255 if bitdepth == 8 else 65535
    rows = []
    for y in range(h):
        row = bytearray()
        for x in range(w):
            r = int((x / max(1, w-1)) * chan_max)
            g = int((y / max(1, h-1)) * chan_max)
            b = rng.randrange(0, chan_max + 1) if (x + y) % 7 == 0 else int(((x+y)/max(1, w+h-2)) * chan_max)
            if bitdepth == 8:
                row += bytes((r, g, b))
            else:
                row += struct.pack('>HHH', r, g, b)
        rows.append(bytes(row))
    return rows


def _build_rows_rgba(w: int, h: int, bitdepth: int, rng: random.Random) -> List[bytes]:
    chan_max = 255 if bitdepth == 8 else 65535
    rows = []
    for y in range(h):
        row = bytearray()
        for x in range(w):
            r = int((x / max(1, w-1)) * chan_max)
            g = int((y / max(1, h-1)) * chan_max)
            b = int((((x^y) % max(1, w)) / max(1, w-1)) * chan_max) if w > 1 else 0
            a = 0 if (x+y) % 5 else int(chan_max * 0.5)  # some transparency
            if bitdepth == 8:
                row += bytes((r, g, b, a))
            else:
                row += struct.pack('>HHHH', r, g, b, a)
        rows.append(bytes(row))
    return rows


def _make_png(rng: random.Random) -> bytes:
    # Choose dimensions within reasonable bounds to keep file small
    w = rng.randint(1, 64)
    h = rng.randint(1, 64)

    # Choose a color type and compatible bit depth
    # Color types: 0=grayscale, 2=RGB, 6=RGBA
    colortype = rng.choices([0, 2, 6], weights=[2, 3, 3], k=1)[0]
    if colortype == 0:
        bitdepth = rng.choice([1, 2, 4, 8, 16])
    else:
        bitdepth = rng.choice([8, 16])

    # Build raw scanlines with filter byte 0 per row
    if colortype == 0:
        rows = _build_rows_grayscale(w, h, bitdepth, rng)
    elif colortype == 2:
        rows = _build_rows_rgb(w, h, bitdepth, rng)
    else:
        rows = _build_rows_rgba(w, h, bitdepth, rng)

    raw = _filter_none_scanlines(0, rows)

    chunks = []
    chunks.append(_ihdr(w, h, bitdepth, colortype, interlace=0))

    # Optionally add ancillary chunks in varied order (valid: before IDAT)
    if rng.random() < 0.6:
        # Common sRGB/gamma-like hint; use gAMA with 45455 (~2.2 gamma) or 100000 (1.0)
        gamma_val = rng.choice([45455, 100000, 50000, 70000])
        chunks.append(_chunk_gama(gamma_val))
    if rng.random() < 0.5:
        # pixels per meter, or unitless (unit=0). 2835 ~ 72 DPI, 3780 ~ 96 DPI
        unit = rng.choice([0, 1])
        ppux = rng.choice([2835, 3780, 11811, 1])
        ppuy = rng.choice([2835, 3780, 11811, 1])
        chunks.append(_chunk_phys(ppux, ppuy, unit))
    if rng.random() < 0.4:
        chunks.append(_chunk_text("Title", "libgd fuzz seed"))
        if rng.random() < 0.5:
            chunks.append(_chunk_text("Author", "generator"))

    # One or more IDATs: we can split compressed stream into multiple chunks
    compressed = zlib.compress(raw, level=rng.choice([1, 6, 9]))
    if len(compressed) > 0 and rng.random() < 0.5:
        # split into 2-3 chunks at random boundaries
        parts = []
        start = 0
        splits = sorted({rng.randrange(1, len(compressed)) for _ in range(rng.randint(1, 2))})
        splits.append(len(compressed))
        for s in splits:
            parts.append(compressed[start:s])
            start = s
        for p in parts:
            chunks.append(_png_chunk(b'IDAT', p))
    else:
        chunks.append(_png_chunk(b'IDAT', compressed))

    chunks.append(_iend())

    return PNG_SIG + b''.join(chunks)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Occasionally generate a tiny fixed image known-good baseline (1x1 RGBA)
    if rng.random() < 0.1:
        w, h, bitdepth, colortype = 1, 1, 8, 6
        rows = [bytes([255, 0, 0, 0])]
        raw = _filter_none_scanlines(0, rows)
        png = PNG_SIG + _ihdr(w, h, bitdepth, colortype) + _idat(raw) + _iend()
        return png

    # Default: varied valid PNG
    png = _make_png(rng)
    # Ensure we respect size limit
    if len(png) > 4096:
        # Re-roll with smaller dims if oversized
        rng2 = random.Random(seed ^ 0xA5A5)
        w = rng2.randint(1, 32)
        h = rng2.randint(1, 32)
        colortype = rng2.choice([0, 2, 6])
        bitdepth = 8 if colortype in (2, 6) else rng2.choice([1, 2, 4, 8])
        if colortype == 0:
            rows = _build_rows_grayscale(w, h, bitdepth, rng2)
        elif colortype == 2:
            rows = _build_rows_rgb(w, h, bitdepth, rng2)
        else:
            rows = _build_rows_rgba(w, h, bitdepth, rng2)
        raw = _filter_none_scanlines(0, rows)
        png = PNG_SIG + _ihdr(w, h, bitdepth, colortype) + _idat(raw) + _iend()
    return png

import random
import struct
from typing import List, Tuple

# Generate valid GIF (87a/89a) buffers suitable for libgd decoders.

class BitPacker:
    def __init__(self):
        self.bits = 0
        self.nbits = 0
        self.out = bytearray()
    def put(self, value: int, width: int):
        self.bits |= (value & ((1 << width) - 1)) << self.nbits
        self.nbits += width
        while self.nbits >= 8:
            self.out.append(self.bits & 0xFF)
            self.bits >>= 8
            self.nbits -= 8
    def flush(self):
        if self.nbits:
            self.out.append(self.bits & 0xFF)
            self.bits = 0
            self.nbits = 0
        return bytes(self.out)

def chunk_subblocks(data: bytes) -> bytes:
    out = bytearray()
    i = 0
    n = len(data)
    while i < n:
        take = min(255, n - i)
        out.append(take)
        out.extend(data[i:i+take])
        i += take
    out.append(0)
    return bytes(out)

def lzw_encode_indices(indices: List[int], min_code_size: int) -> bytes:
    clear_code = 1 << min_code_size
    end_code = clear_code + 1
    next_code = end_code + 1
    code_size = min_code_size + 1
    max_code_for_size = (1 << code_size) - 1

    def bump():
        nonlocal code_size, max_code_for_size
        code_size += 1
        max_code_for_size = (1 << code_size) - 1

    dict_map = {}
    for i in range(clear_code):
        dict_map[(i,)] = i

    pack = BitPacker()
    pack.put(clear_code, code_size)

    w = ()
    for k in indices:
        wk = (k,) if not w else (w + (k,))
        if wk in dict_map:
            w = wk
        else:
            pack.put(dict_map[w], code_size)
            dict_map[wk] = next_code
            next_code += 1
            if next_code > max_code_for_size:
                if code_size < 12:
                    bump()
                else:
                    pack.put(clear_code, code_size)
                    code_size = min_code_size + 1
                    max_code_for_size = (1 << code_size) - 1
                    dict_map = { (i,): i for i in range(clear_code) }
                    next_code = end_code + 1
            w = (k,)
    if w:
        pack.put(dict_map[w], code_size)
    pack.put(end_code, code_size)
    return pack.flush()

def palette_rgb(n: int, rng: random.Random) -> List[Tuple[int,int,int]]:
    entries: List[Tuple[int,int,int]] = []
    base_colors = [
        (0,0,0), (255,255,255), (255,0,0), (0,255,0), (0,0,255),
        (255,255,0), (255,0,255), (0,255,255)
    ]
    i = 0
    while i < n and i < len(base_colors):
        entries.append(base_colors[i])
        i += 1
    while i < n:
        entries.append((rng.randrange(256), rng.randrange(256), rng.randrange(256)))
        i += 1
    return entries

def pack_palette(pal: List[Tuple[int,int,int]]) -> bytes:
    b = bytearray()
    for r,g,bv in pal:
        b.extend([r,g,bv])
    return bytes(b)

def choose_ct_size(ncolors: int) -> int:
    size = 2
    s = 0
    while size < ncolors and size < 256:
        size <<= 1
        s += 1
    return s

def build_image_desc(x: int, y: int, w: int, h: int, lct_flag: bool, interlace: bool, lct_size_pow: int) -> bytes:
    b = bytearray()
    b.append(0x2C)
    b.extend(struct.pack('<HHHH', x, y, w, h))
    packed = 0
    if lct_flag:
        packed |= 0x80
    if interlace:
        packed |= 0x40
    packed |= (lct_size_pow & 0x07)
    b.append(packed)
    return bytes(b)

def build_gce(trans: bool, trans_index: int, delay_cs: int, disposal: int) -> bytes:
    b = bytearray()
    b.extend(b"\x21\xF9\x04")
    packed = 0
    disposal = max(0, min(disposal, 7))
    packed |= (disposal & 0x7) << 2
    if trans:
        packed |= 0x01
    b.append(packed)
    b.extend(struct.pack('<H', delay_cs))
    b.append(trans_index & 0xFF)
    b.append(0)
    return bytes(b)

def build_comment(rng: random.Random) -> bytes:
    text = ("Generated by seed %d" % rng.randrange(1_000_000)).encode('ascii', 'ignore')
    return b"\x21\xFE" + chunk_subblocks(text)

def build_app_loop(loop_count: int) -> bytes:
    b = bytearray()
    b.extend(b"\x21\xFF\x0BNETSCAPE2.0\x03\x01")
    b.extend(struct.pack('<H', loop_count & 0xFFFF))
    b.append(0)
    return bytes(b)

def build_plain_text_ext(w: int, h: int) -> bytes:
    b = bytearray()
    b.extend(b"\x21\x01")
    b.append(12)
    b.extend(struct.pack('<HHHHBBBB', 0, 0, w, h, 8, 8, 0, 1))
    b.append(0)
    return bytes(b)

def make_frame_indices(w: int, h: int, palette_len: int, pattern: str, rng: random.Random) -> List[int]:
    indices = [0] * (w*h)
    if palette_len <= 0:
        palette_len = 2
    if pattern == 'solid':
        color = rng.randrange(min(palette_len, max(1, palette_len)))
        for i in range(w*h):
            indices[i] = color
    elif pattern == 'checker':
        c0 = 1 % palette_len
        c1 = 2 % palette_len
        for y in range(h):
            for x in range(w):
                indices[y*w + x] = c0 if ((x ^ y) & 1) == 0 else c1
    elif pattern == 'gradient_h':
        for y in range(h):
            for x in range(w):
                indices[y*w + x] = int((x / max(1, w-1)) * (palette_len - 1))
    elif pattern == 'gradient_v':
        for y in range(h):
            val = int((y / max(1, h-1)) * (palette_len - 1))
            for x in range(w):
                indices[y*w + x] = val
    else:
        for i in range(w*h):
            indices[i] = rng.randrange(palette_len)
    return indices

def build_image_block(w: int, h: int, indices: List[int], palette_len: int) -> bytes:
    nbits = 1
    size = 2
    while size < max(2, palette_len):
        size <<= 1
        nbits += 1
    min_code_size = max(2, nbits)
    lzw_stream = lzw_encode_indices(indices, min_code_size)
    return bytes([min_code_size]) + chunk_subblocks(lzw_stream)

def safe_randrange(rng: random.Random, start: int, stop_inclusive: int) -> int:
    # Returns a number in [start, stop_inclusive], handles start==stop gracefully.
    if stop_inclusive <= start:
        return start
    return rng.randrange(start, stop_inclusive + 1)

def build_gif(seed: int) -> bytes:
    rng = random.Random(seed)

    use_89a = rng.choice([True, False, True])
    header = b"GIF89a" if use_89a else b"GIF87a"

    w = rng.choice([1, 2, 3, 4, 8, 16, 32, 64])
    h = rng.choice([1, 2, 3, 4, 8, 16, 32, 64])

    use_gct = rng.choice([True, False, True])

    ncolors = rng.choice([2, 4, 8, 16, 32, 64, 128, 256])
    gct_pow = choose_ct_size(ncolors)
    gct_len = 1 << (gct_pow + 1)

    bg_index = rng.randrange(gct_len) if use_gct else 0
    aspect = 0

    packed = 0
    if use_gct:
        packed |= 0x80
        packed |= 0x70
        packed |= (gct_pow & 0x7)

    lsd = struct.pack('<HHBBB', w, h, packed, bg_index, aspect)

    out = bytearray()
    out += header
    out += lsd

    gct = None
    if use_gct:
        gct = palette_rgb(gct_len, rng)
        out += pack_palette(gct)

    if use_89a and rng.random() < 0.7:
        out += build_comment(rng)
    animated = use_89a and rng.random() < 0.6 and (w*h) <= 4096
    if use_89a and animated:
        out += build_app_loop(rng.choice([0, 1, 5, 10, 100]))
    if use_89a and rng.random() < 0.2:
        out += build_plain_text_ext(w, h)

    frames = rng.choice([1, 1, 2, 3]) if animated else 1

    for _ in range(frames):
        use_lct = rng.choice([False, True]) if use_gct else True
        if use_lct:
            lct_colors = rng.choice([2, 4, 8, 16, 32, 64, 128, 256])
            lct_pow = choose_ct_size(lct_colors)
            lct_len = 1 << (lct_pow + 1)
            pal = palette_rgb(lct_len, rng)
        else:
            pal = gct
            lct_pow = 0
            lct_len = len(pal) if pal else 2

        trans = use_89a and rng.random() < 0.5
        trans_index = rng.randrange(lct_len)
        delay_cs = rng.choice([0, 2, 5, 10, 20, 50, 100]) if animated else 0
        disposal = rng.choice([0, 1, 2, 3])
        if use_89a:
            out += build_gce(trans, trans_index if trans else 0, delay_cs, disposal)

        if rng.random() < 0.7:
            ix, iy, iw, ih = 0, 0, w, h
        else:
            # Safe random ranges; handle small w/h
            iw = safe_randrange(rng, 1, max(1, w))
            ih = safe_randrange(rng, 1, max(1, h))
            ix = safe_randrange(rng, 0, max(0, w - iw))
            iy = safe_randrange(rng, 0, max(0, h - ih))

        interlace = rng.random() < 0.15
        out += build_image_desc(ix, iy, iw, ih, use_lct, interlace, lct_pow)

        if use_lct:
            out += pack_palette(pal)

        palette_for_indices = lct_len if use_lct else (len(gct) if gct else 2)
        pattern = rng.choice(['solid', 'checker', 'gradient_h', 'gradient_v', 'noise'])
        indices = make_frame_indices(iw, ih, palette_for_indices, pattern, rng)

        if trans:
            # sprinkle some transparent pixels
            for _ in range(min(10, max(1, len(indices)//8))):
                pos = rng.randrange(len(indices))
                indices[pos] = trans_index

        out += build_image_block(iw, ih, indices, palette_for_indices)

    out.append(0x3B)
    return bytes(out)


def generate(seed: int) -> bytes:
    data = build_gif(seed)
    if len(data) > 4096:
        rng = random.Random((seed ^ 0xA5A5A5A5) & 0xFFFFFFFF)
        def small_gif() -> bytes:
            hdr = b"GIF89a"
            w, h = 8, 8
            packed = 0xF0 | 0  # GCT present, 8-bit color resolution, size pow=0 -> 2 colors
            lsd = struct.pack('<HHBBB', w, h, packed, 0, 0)
            out = bytearray(hdr + lsd)
            out += pack_palette([(0,0,0), (255,255,255)])
            out += build_gce(True, 0, 0, 0)
            out += build_image_desc(0,0,w,h, False, False, 0)
            indices = make_frame_indices(w,h,2,'checker', rng)
            out += build_image_block(w,h,indices,2)
            out.append(0x3B)
            return bytes(out)
        data = small_gif()
    return data

import random
import struct
from typing import List, Tuple

# WBMP (Wireless Bitmap) generator
# Spec summary (Type 0, B/W, uncompressed):
#  - TypeField: 1 byte, upper 4 bits Type (0), lower 4 bits FixHeader (0) -> 0x00
#  - FixHeaderField: 0x00 (already in low nibble of the first byte when Type=0)
#  - Width:  WBI (WBMP Integer)
#  - Height: WBI
#  - Image Data: rows of packed bits, MSB first each byte, row padded to full bytes
# WBI (WBMP Integer): big-endian base-128, 7 bits per byte with continuation bit 0x80.
#  For 0: single byte 0x00 is valid encoding.

MAX_SIZE = 4096

def _wbi_encode(n: int) -> bytes:
    # Encode non-negative integer into WBMP Integer (big-endian base-128, MSB=cont bit)
    if n < 0:
        n = 0
    # 0 encodes as 0x00
    if n == 0:
        return b"\x00"
    chunks: List[int] = []
    while n > 0:
        chunks.append(n & 0x7F)
        n >>= 7
    chunks.reverse()
    out = bytearray()
    for i, c in enumerate(chunks):
        if i != len(chunks) - 1:
            out.append(0x80 | c)
        else:
            out.append(c)
    return bytes(out)

def _row_bytes(width: int) -> int:
    return (max(0, width) + 7) // 8

def _gen_pattern(width: int, height: int, mode: str, rng: random.Random) -> bytes:
    rb = _row_bytes(width)
    data = bytearray(rb * height)
    if width <= 0 or height <= 0:
        return bytes(data)

    if mode == "solid0":
        # all zeros
        return bytes(data)
    if mode == "solid1":
        for i in range(len(data)):
            data[i] = 0xFF
        # Mask out padding bits on each row to keep them consistent
        pad = rb * 8 - width
        if pad:
            mask = 0xFF & (0xFF << pad)
            for y in range(height):
                data[y*rb + rb - 1] &= mask
        return bytes(data)
    if mode == "checker":
        for y in range(height):
            for x in range(width):
                bit = ((x ^ y) & 1)
                if bit:
                    byte_index = y*rb + (x // 8)
                    bit_in_byte = 7 - (x % 8)
                    data[byte_index] |= (1 << bit_in_byte)
        return bytes(data)
    if mode == "vstripes":
        for x in range(width):
            if (x // 3) % 2 == 0:
                for y in range(height):
                    byte_index = y*rb + (x // 8)
                    bit_in_byte = 7 - (x % 8)
                    data[byte_index] |= (1 << bit_in_byte)
        return bytes(data)
    if mode == "hstripes":
        for y in range(height):
            if (y // 3) % 2 == 1:
                # set full row to ones
                for b in range(rb):
                    data[y*rb + b] = 0xFF
        pad = rb * 8 - width
        if pad:
            mask = 0xFF & (0xFF << pad)
            for y in range(height):
                data[y*rb + rb - 1] &= mask
        return bytes(data)
    if mode == "noise":
        for y in range(height):
            for b in range(rb):
                data[y*rb + b] = rng.getrandbits(8)
        pad = rb * 8 - width
        if pad:
            mask = 0xFF & (0xFF << pad)
            for y in range(height):
                data[y*rb + rb - 1] &= mask
        return bytes(data)
    return bytes(data)

def _pick_dims(rng: random.Random) -> Tuple[int, int]:
    # Favor a variety of edge and typical sizes while keeping total under MAX_SIZE
    choices = [
        (0, 0), (1, 1), (1, 8), (8, 1), (7, 7), (8, 8), (15, 15), (16, 16),
        (31, 31), (32, 32), (63, 63), (64, 64), (127, 1), (1, 127), (127, 127),
        (200, 50), (50, 200), (100, 100), (300, 10), (10, 300)
    ]
    # Random fallback sizes
    for _ in range(5):
        w = rng.randint(0, 256)
        h = rng.randint(0, 256)
        choices.append((w, h))

    rng.shuffle(choices)
    for w, h in choices:
        header_len = 1 + len(_wbi_encode(w)) + len(_wbi_encode(h))
        data_len = _row_bytes(w) * max(0, h)
        if header_len + data_len <= MAX_SIZE:
            return w, h
    # fallback to a small guaranteed size
    return 16, 16

def _build_wbmp(width: int, height: int, payload: bytes) -> bytes:
    # Type 0, FixHeader 0 -> first byte 0x00
    header = bytearray()
    header.append(0x00)
    header += _wbi_encode(width)
    header += _wbi_encode(height)
    return bytes(header) + payload

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose dimensions
    w, h = _pick_dims(rng)

    # Choose pattern to trigger diverse decoder paths
    modes = ["solid0", "solid1", "checker", "vstripes", "hstripes", "noise"]
    mode = rng.choice(modes)

    payload = _gen_pattern(w, h, mode, rng)
    blob = _build_wbmp(w, h, payload)

    # As an additional interesting case, sometimes prepend (or not) an optional leading 0x00 is not allowed
    # in WBMP header beyond the specified first byte, so we keep to strict spec and avoid extras.

    # Ensure size bound
    if len(blob) > MAX_SIZE:
        # Reduce by cropping height
        rb = _row_bytes(w)
        max_rows = max(0, (MAX_SIZE - (1 + len(_wbi_encode(w)) + len(_wbi_encode(h)))) // max(1, rb))
        h2 = min(h, max_rows)
        payload = payload[:rb * h2]
        blob = _build_wbmp(w, h2, payload)

    return blob

import random
import struct

def _wbmp_header(type_field: int, fix_header: int, width: int, height: int) -> bytes:
    # WBMP (WAP Bitmap) Type 0 (B/W, uncompressed, 1-bit) common
    # Header fields:
    #  - TypeField: 1 byte (usually 0)
    #  - FixHeaderField: 1 byte; bit7=1 if any extended fields follow. We keep simple: 0
    #  - Width, Height: multi-byte integers in WBMP variable-length integer (MBI) format (7-bit groups, msb=1 continuation)
    return bytes([type_field & 0xFF, fix_header & 0xFF]) + _wbmp_mbi(width) + _wbmp_mbi(height)


def _wbmp_mbi(n: int) -> bytes:
    # Multi-Byte Integer encoding: big-endian 7-bit groups, high bit set for all but last
    if n < 0:
        n = 0
    groups = []
    groups.append(n & 0x7F)
    n >>= 7
    while n:
        groups.append((n & 0x7F) | 0x80)  # mark continuation for previous groups
        n >>= 7
    # groups currently little-endian; reverse to big-endian with final group continuation bit cleared
    groups = groups[::-1]
    # Ensure only the last (least significant) group has msb=0
    out = bytearray()
    for i, g in enumerate(groups):
        if i != len(groups) - 1:
            out.append(g | 0x80)
        else:
            out.append(g & 0x7F)
    return bytes(out)


def _pack_rows_1bpp(width: int, height: int, pattern: int) -> bytes:
    # pattern selects how to generate pixels
    row_bytes = (width + 7) // 8
    buf = bytearray()
    for y in range(height):
        row = bytearray(row_bytes)
        if pattern == 0:
            # all white (0) or all black (1)
            fill_one = (y % 2) == 1
            val = 0xFF if fill_one else 0x00
            row[:] = bytes([val]) * row_bytes
            # If width not multiple of 8, clear tail bits to 0 for consistency
            if width % 8:
                tail_bits = 8 - (width % 8)
                row[-1] &= (0xFF << tail_bits) & 0xFF
        elif pattern == 1:
            # horizontal stripes: alternate lines of 0xAA/0x55
            val = 0xAA if (y % 2 == 0) else 0x55
            row[:] = bytes([val]) * row_bytes
            if width % 8:
                tail_bits = 8 - (width % 8)
                row[-1] &= (0xFF << tail_bits) & 0xFF
        elif pattern == 2:
            # vertical stripes
            for x in range(width):
                bit = 1 if (x // 2) % 2 == 0 else 0
                if bit:
                    byte_index = x // 8
                    bit_index = 7 - (x % 8)
                    row[byte_index] |= (1 << bit_index)
        else:
            # checkerboard
            for x in range(width):
                bit = ((x // 2) + (y // 2)) % 2
                if bit:
                    byte_index = x // 8
                    bit_index = 7 - (x % 8)
                    row[byte_index] |= (1 << bit_index)
        buf.extend(row)
    return bytes(buf)


def _generate_wbmp(seed: int) -> bytes:
    rnd = random.Random(seed)

    # Choose WBMP type among typical supported ones. libgd commonly supports type 0 (B/W)
    type_field = 0  # B/W, 1-bit, uncompressed

    # No extended header fields
    fix_header = 0

    # Choose diverse dimensions but keep total size <= 4096
    # Aim for various cases: tiny, small, wide, tall, powers of two, odd widths
    candidates = [
        (1, 1), (1, 8), (8, 1), (7, 7), (16, 16), (31, 5), (5, 31),
        (32, 32), (33, 33), (64, 3), (3, 64), (100, 50), (50, 100),
        (128, 64), (64, 128), (240, 1), (1, 240), (200, 200), (300, 10), (10, 300)
    ]

    # Also random dimension ensuring payload cap
    def pick_dims():
        # Try random up to 512 but cap by size
        for _ in range(10):
            w = rnd.randint(1, 400)
            h = rnd.randint(1, 400)
            row_bytes = (w + 7) // 8
            size = 2 + len(_wbmp_mbi(w)) + len(_wbmp_mbi(h)) + row_bytes * h
            if size <= 4096:
                return (w, h)
        return rnd.choice(candidates)

    if rnd.random() < 0.5:
        width, height = rnd.choice(candidates)
    else:
        width, height = pick_dims()

    # Create a few different pixel patterns
    pattern = rnd.randrange(0, 4)

    header = _wbmp_header(type_field, fix_header, width, height)
    body = _pack_rows_1bpp(width, height, pattern)

    data = header + body
    # Ensure not exceeding 4096 bytes
    return data[:4096]


def generate(seed: int) -> bytes:
    return _generate_wbmp(seed)

import random
import struct
import zlib

# This generator produces small ISO-BMFF containers resembling AVIF/HEIF files
# with minimal structure to exercise libgd HEIF/AVIF loaders. Payloads are
# simplistic and may not decode, but the box structure aims to be accepted
# far enough to exercise parsing paths.


def be32(n: int) -> bytes:
    return struct.pack(">I", n)


def be16(n: int) -> bytes:
    return struct.pack(">H", n)


def be8(n: int) -> bytes:
    return struct.pack("B", n & 0xFF)


def box(ftype: bytes, payload: bytes) -> bytes:
    return be32(len(payload) + 8) + ftype + payload


def ftyp_box(major: bytes, minor: int, brands: list[bytes]) -> bytes:
    payload = major + be32(minor)
    for b in brands:
        payload += b
    return box(b"ftyp", payload)


# ImageSpatialExtents

def make_ispe(width: int, height: int) -> bytes:
    payload = b"\x00\x00\x00\x00" + be32(width) + be32(height)
    return box(b"ispe", payload)


# PixelInformation

def make_pixi(components: int, bits: int) -> bytes:
    payload = b"\x00\x00\x00\x00" + be8(components) + bytes([bits] * components)
    return box(b"pixi", payload)


# AV1 Codec Configuration (minimal placeholder)

def make_av1C() -> bytes:
    conf = bytearray()
    conf += be8(1)  # marker/version
    conf += be8(0)
    conf += be8(0)
    conf += be8(0)
    return box(b"av1C", bytes(conf))


# nclx color info

def make_colr_nclx() -> bytes:
    payload = b"nclx" + be16(1) + be16(1) + be16(1) + be8(0)
    return box(b"colr", payload)


def make_ipco(props: list[bytes]) -> bytes:
    return box(b"ipco", b"".join(props))


# ItemPropertyAssociation (version 0, simple 7-bit indices, one item)

def make_ipma(item_id: int, prop_indices: list[int]) -> bytes:
    version = 0
    hdr = be8(version) + b"\x00\x00\x00"
    entry_count = be32(1)
    entry = be16(item_id) + be8(len(prop_indices))
    for idx in prop_indices:
        entry += be8(idx & 0x7F)  # essential=0
    return box(b"ipma", hdr + entry_count + entry)


# ItemInfoEntry (version 2)

def make_infe(item_id: int, item_type: bytes, name: bytes = b"img") -> bytes:
    version = 2
    hdr = be8(version) + b"\x00\x00\x00"
    body = be16(item_id) + be16(0)
    body += item_type
    body += name + b"\x00" + b"\x00" + b"\x00"
    return box(b"infe", hdr + body)


def make_iinf(entries: list[bytes]) -> bytes:
    version = 0
    hdr = be8(version) + b"\x00\x00\x00"
    return box(b"iinf", hdr + be16(len(entries)) + b"".join(entries))


# ItemLocation with one extent. Use base_offset=0 and extent_offset into mdat data.

def make_iloc(item_id: int, base_offset: int, extent_offset: int, extent_length: int) -> bytes:
    version = 0
    offset_size = 4
    length_size = 4
    base_offset_size = 8
    index_size = 0
    sizes = ((offset_size & 0xF) << 4) | (length_size & 0xF)
    sizes2 = ((base_offset_size & 0xF) << 4) | (index_size & 0xF)
    hdr = be8(version) + b"\x00\x00\x00" + be8(sizes) + be8(sizes2) + be16(1)
    entry = be16(item_id) + be16(1) + struct.pack(">Q", base_offset)
    entry += be32(extent_offset) + be32(extent_length)
    return box(b"iloc", hdr + entry)


def make_iref_empty() -> bytes:
    version = 0
    hdr = be8(version) + b"\x00\x00\x00" + be32(0)
    return box(b"iref", hdr)


def make_pitm(item_id: int) -> bytes:
    version = 0
    hdr = be8(version) + b"\x00\x00\x00" + be16(item_id)
    return box(b"pitm", hdr)


def make_meta(children: list[bytes]) -> bytes:
    header = b"\x00\x00\x00\x00"
    return box(b"meta", header + b"".join(children))


def make_moov_with_meta(meta_box: bytes) -> bytes:
    return box(b"moov", meta_box)


def make_mdat(payload: bytes) -> bytes:
    return box(b"mdat", payload)


def make_av1_payload(seed: int, size: int) -> bytes:
    rng = random.Random(seed)
    data = bytearray()
    data += b"\x12\x00"
    data += bytes(rng.getrandbits(8) for _ in range(max(0, size - len(data))))
    return bytes(data)


def build_avif(seed: int, width: int, height: int, chroma: str) -> bytes:
    rng = random.Random(seed)

    # File type: avif with common compatible brands
    ftyp = ftyp_box(b"avif", 0, [b"avif", b"mif1", b"miaf", b"isom"])

    ispe = make_ispe(width, height)
    pixi = make_pixi(3, 8)
    colr = make_colr_nclx()
    av1c = make_av1C()

    ipco = make_ipco([ispe, pixi, colr, av1c])
    ipma = make_ipma(1, [1, 2, 3, 4])

    iinf = make_iinf([make_infe(1, b"av01", b"Primary")])
    pitm = make_pitm(1)

    payload = make_av1_payload(seed ^ 0xA5A5, rng.randint(32, 128))
    mdat = make_mdat(payload)

    iloc = make_iloc(1, 0, 0, len(payload))
    iref = make_iref_empty()

    meta = make_meta([pitm, iinf, ipco, ipma, iloc, iref])
    moov = make_moov_with_meta(meta)

    return ftyp + moov + mdat


def make_hvcC() -> bytes:
    data = b"\x01\x01\x60\x00\x00\x00\x00\x00"
    return box(b"hvcC", data)


def build_heic(seed: int, width: int, height: int) -> bytes:
    rng = random.Random(seed)
    ftyp = ftyp_box(b"heic", 0, [b"heic", b"mif1", b"miaf", b"isom"])
    ispe = make_ispe(width, height)
    pixi = make_pixi(3, 8)
    colr = make_colr_nclx()
    hvcc = make_hvcC()
    ipco = make_ipco([ispe, pixi, colr, hvcc])
    ipma = make_ipma(1, [1, 2, 3, 4])
    iinf = make_iinf([make_infe(1, b"hvc1", b"Primary")])
    pitm = make_pitm(1)
    payload = zlib.compress(bytes(rng.getrandbits(8) for _ in range(rng.randint(16, 64))))
    mdat = make_mdat(payload)
    iloc = make_iloc(1, 0, 0, len(payload))
    iref = make_iref_empty()
    meta = make_meta([pitm, iinf, ipco, ipma, iloc, iref])
    moov = make_moov_with_meta(meta)
    return ftyp + moov + mdat


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    width = rng.choice([1, 2, 4, 8, 16, 32])
    height = rng.choice([1, 2, 4, 8, 16, 32])
    chroma = rng.choice(["420", "422", "444"])  # kept for variability

    if rng.random() < 0.6:
        data = build_avif(seed, width, height, chroma)
    else:
        data = build_heic(seed, width, height)

    if len(data) > 4096:
        data = data[:4096]
    return data
